/* @lc app=leetcode id=1862 lang=kotlin */ class Solution { fun sumOfFlooredPairs(nums: IntArray): Int = (nums.maxOrNull() ?: 0).let { max -> IntArray(max + 1).apply { nums.forEach { this[it]++ } }.let { freq -> IntArray(max + 1).apply { (1..max).forEach { this[it] = this[it - 1] + freq[it] } }.let { pref -> (1..max).filter { freq[it] > 0 }.fold(0L) { sum, x -> (sum + (x..max step x).fold(0L) { acc, y -> acc + (y / x).toLong() * (pref[minOf(y + x - 1, max)] - pref[y - 1]) } % 1000000007 * freq[x]) % 1000000007 }.toInt() } } } }